import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"{% content %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Переменные","slug":"переменные","link":"#переменные","children":[]},{"level":2,"title":"Сохранение содержимого в Twig-переменную","slug":"сохранение-содержимого-в-twig-переменную","link":"#сохранение-содержимого-в-twig-переменную","children":[]},{"level":2,"title":"Проверка существования файла контента","slug":"проверка-существования-фаила-контента","link":"#проверка-существования-фаила-контента","children":[]},{"level":2,"title":"Парсинг контента как строки","slug":"парсинг-контента-как-строки","link":"#парсинг-контента-как-строки","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/markup/tag/content.md","filePath":"3.x/ru/markup/tag/content.md"}'),u={name:"3.x/ru/markup/tag/content.md"};function g(r,n,k,d,m,w){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"{% content %}",-1)),s(e),n[1]||(n[1]=i(`<p>Тег <code>{% content %}</code> отображает <a href="./../../cms/themes/content.html">блок контента CMS</a> на странице. Чтобы отобразить блок контента с именем <strong>contacts.htm</strong>, передайте имя файла после тега <code>content</code> в кавычках как строку.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>contacts.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Блок контента в поддиректории рендерится аналогичным образом.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/content.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../cms/themes/themes.html">Документация по темам</a> содержит подробности об использовании поддиректорий.</p></div><p>Блоки контента могут рендериться как обычный текст:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>readme.txt<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Также можно использовать синтаксис Markdown:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>changelog.md<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Блоки контента можно использовать в сочетании с <a href="./../../cms/themes/layouts.html">плейсхолдерами макетов</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> sidebar <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>sidebar-content.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="переменные"><a href="#переменные" class="header-anchor">#</a> Переменные</h2><p>Вы можете передавать переменные в блоки контента, указав их после имени файла:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> name<span class="token operator">=</span>user<span class="token punctuation">.</span>name <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете назначать новые переменные для использования в контенте:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>location.htm<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Внутри контента к переменным можно обращаться с помощью базового синтаксиса с одинарными <em>фигурными скобками</em>:</p><div class="language- extra-class"><pre class="language-text"><code>&lt;p&gt;Country: {country}, city: {city}.&lt;/p&gt;
</code></pre></div><p>Вы также можете передать коллекцию переменных как простой массив:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> likes<span class="token operator">=</span><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Dogs<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Fishing<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Golf<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span>
<span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Доступ к коллекции переменных осуществляется с помощью открывающего и закрывающего набора скобок:</p><div class="language- extra-class"><pre class="language-text"><code>&lt;ul&gt;
    {likes}
        &lt;li&gt;{name}&lt;/li&gt;
    {/likes}
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>Примечание</strong>: Синтаксис Twig не поддерживается в блоках контента. Рассмотрите возможность использования <a href="./../cms/partials.html">CMS-фрагмента</a>.</p></blockquote><h2 id="сохранение-содержимого-в-twig-переменную"><a href="#сохранение-содержимого-в-twig-переменную" class="header-anchor">#</a> Сохранение содержимого в Twig-переменную</h2><p>В любом шаблоне вы можете сохранить содержимое в переменную с помощью функции <code>content()</code>. Это позволяет манипулировать выводом перед отображением. Не забудьте использовать фильтр <code>|raw</code>, чтобы предотвратить экранирование вывода.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> welcomeContent<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Вы также можете передать переменные в контент как второй аргумент.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="проверка-существования-фаила-контента"><a href="#проверка-существования-фаила-контента" class="header-anchor">#</a> Проверка существования файла контента</h2><p>Функция <code>hasContent()</code> может использоваться для проверки существования контента без его рендеринга. Чтобы предотвратить рендеринг контента, передайте второй аргумент как false — функция вернёт true или false в зависимости от того, найден ли файл контента.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasContent<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome content not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="парсинг-контента-как-строки"><a href="#парсинг-контента-как-строки" class="header-anchor">#</a> Парсинг контента как строки</h2><p>При использовании тега <code>{% content %}</code> он автоматически разрешает <a href="./../../cms/themes/snippets.html">CMS-сниппеты</a> и ссылки, созданные <a href="./../../element/form/widget-pagefinder.html">виджетом формы поиска страниц</a>.</p><p>Аналогично, фильтр <code>|content</code> может использоваться для парсинга HTML-строки на предмет нескольких объектов контента и их разрешения в выводе.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Фильтр <code>|md</code> также можно использовать для парсинга Markdown-контента, содержащегося в строке.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>markdown_content<span class="token operator">|</span>md<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../cms/themes/snippets.html">CMS-сниппеты</a></li><li><a href="./../../markup/filter/link.html">Twig-фильтр Link</a></li><li><a href="./../../markup/filter/md.html">Twig-фильтр Markdown</a></li></ul></div>`,39))])}const f=p(u,[["render",g]]);export{v as __pageData,f as default};
